            return "(" + name + " was never added)";
        }
        java.awt.GridBagConstraints gc =
                ((java.awt.GridBagLayout) panel.getLayout()).getConstraints(c);
        return "gridx=" + gc.gridx + " gridy=" + gc.gridy + " weightx=" + gc.weightx
