import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;

public class GridBagLabelFieldForm extends JPanel {

    private final JLabel nameLabel = new JLabel("Name");
    private final JLabel emailLabel = new JLabel("Email");
    private final JLabel phoneLabel = new JLabel("Phone");
    private final JTextField nameField = new JTextField(16);
    private final JTextField emailField = new JTextField(16);
    private final JTextField phoneField = new JTextField(16);
    private final JButton saveButton = new JButton("Save");

    public GridBagLabelFieldForm() {
        nameLabel.setName("nameLabel");
        emailLabel.setName("emailLabel");
        phoneLabel.setName("phoneLabel");
        nameField.setName("nameField");
        emailField.setName("emailField");
        phoneField.setName("phoneField");
        saveButton.setName("saveButton");
        buildForm();
    }

    private void buildForm() {
        setLayout(new GridBagLayout());
        JLabel[] labels = { nameLabel, emailLabel, phoneLabel };
        JTextField[] fields = { nameField, emailField, phoneField };

        for (int row = 0; row < labels.length; row++) {
            GridBagConstraints labelSpot = new GridBagConstraints();
            labelSpot.gridx = 0;
            labelSpot.gridy = row;
            labelSpot.weightx = 0.0;
            labelSpot.fill = GridBagConstraints.NONE;
            labelSpot.anchor = GridBagConstraints.WEST;
            labelSpot.insets = new Insets(4, 4, 4, 4);
            add(labels[row], labelSpot);

            GridBagConstraints fieldSpot = new GridBagConstraints();
            fieldSpot.gridx = 1;
            fieldSpot.gridy = row;
            fieldSpot.weightx = 1.0;
            fieldSpot.fill = GridBagConstraints.HORIZONTAL;
            fieldSpot.anchor = GridBagConstraints.WEST;
            fieldSpot.insets = new Insets(4, 4, 4, 4);
            add(fields[row], fieldSpot);
        }

        GridBagConstraints saveSpot = new GridBagConstraints();
        saveSpot.gridx = 1;
        saveSpot.gridy = 3;
        saveSpot.weightx = 0.0;
        saveSpot.fill = GridBagConstraints.NONE;
        saveSpot.anchor = GridBagConstraints.EAST;
        saveSpot.insets = new Insets(8, 4, 4, 4);
        add(saveButton, saveSpot);
    }
}
